days.exerciseText:
/// Block 1 scheme: 2x15 @7 -> 3x15 @7 -> 4x15 ramp, last 2 to failure -> 4x10-12 heavy
/// The logged RPE on the last set back-solves the exercise's 1RM, so next week's
/// suggested weights are calibrated to what the user actually did.
b1 / used: none / 1x15 @7, 1x15 @7+ / 90s / warmup: none / progress: custom() {~
  if (completedRPE[ns] > 0 && completedReps[ns] > 0) {
    rm1 = completedWeights[ns] / rpeMultiplier(completedReps[ns], completedRPE[ns])
  }
~}
b21 / used: none / 1x21 @7, 1x21 @7+ / 90s / warmup: none / progress: custom() { ...b1 }
b20 / used: none / 1x20 @7, 1x20 @7+ / 90s / warmup: none / progress: custom() { ...b1 }
b12 / used: none / 1x12 @7, 1x12 @7+ / 90s / warmup: none / progress: custom() { ...b1 }

Skullcrusher, Barbell[1-4] / ...b1
Triceps Extension, Barbell[1-4] / ...b1
// Use a V-handle.
Triceps Pushdown[1-4] / ...b20
Front Raise[1-4] / ...b1
Upright Row, Barbell[1-4] / ...b1
Incline Bench Press[1-4] / ...b1
Chest Press, Leverage Machine[1-4] / ...b1
Cable Crossover[1-4] / ...b20

Bicep Curl, Barbell[1-4] / ...b1
// Alternate arms.
Bicep Curl[1-4] / ...b1
Concentration Curl[1-4] / ...b1
Seated Row[1-4] / ...b1
High Row[1-4] / ...b1
// Add weight or use band assistance to stay in the target rep range.
Triceps Dip[1-4] / ...b1
// Use a rope attachment.
Triceps Pushdown[1-4] / ...b20

/// Main lift pyramid: effort stays hard the whole way - the 12s and 10s are there
/// to fatigue you before the top set. The final all-out AMRAP updates your 1RM.
main2 / used: none / 1x12 @7, 1x10 @7, 1x8 @8, 1x5 @8, 1x12+ @9+ / 180s / progress: custom() {~
  if (completedReps[ns] > 0) {
    var.est = completedRPE[ns] > 0
      ? completedWeights[ns] / rpeMultiplier(completedReps[ns], completedRPE[ns])
      : calculate1RM(completedWeights[ns], completedReps[ns])
    rm1 = max(rm1, var.est)
  }
~}
/// Accessory pyramid: 12-10-8, adding a set and weight in weeks 7-8.
/// Logged RPE on the last set recalibrates the 1RM (same as block 1).
acc2 / used: none / 1x12 @7, 1x10 @7, 1x8 @8+ / 90s / warmup: none / progress: custom() { ...b1 }

// Pyramid up in weight as the reps drop. Finish with one all-out set of ~12.
Seated Overhead Press[5-8] / ...main2
Shoulder Press[5-8] / ...acc2
Lateral Raise[5-8] / ...acc2
Triceps Dip[5-8] / ...acc2
Skullcrusher[5-8] / ...acc2
//
Triceps Pushdown[5-8] / ...acc2

// ...Seated Overhead Press
Bench Press Close Grip[5-8] / ...main2
Incline Bench Press, Dumbbell[5-8] / ...acc2
Chest Fly[5-8] / ...acc2
// Seated dip machine.
Triceps Dip, Leverage Machine[5-8] / ...acc2
// Two-hand overhead dumbbell extension.
Triceps Extension[5-8] / ...acc2

// High bar, close stance - big range of motion, quads do the work.
// Pyramid up in weight as the reps drop. Finish with one all-out set of ~12.
highbar: Squat[5-8] / ...main2
// Use the hack squat sled or smith machine.
Hack Squat, Smith Machine[5-8] / ...acc2
Step up[5-8] / ...acc2
// Dumbbell RDL.
Romanian Deadlift[5-8] / ...acc2
Back Extension[5-8] / ...acc2

/// Reverse pyramid: heavy top set, back-off 8s, ~15-rep burnout AMRAP.
/// The burnout AMRAP updates your 1RM.
main3 / used: none / 1x5 @7, 3x8 @7, 1x15+ @8+ / 180s / progress: custom() { ...main2 }
/// Accessory reverse pyramid: 5-8-12-15, RPE creeps up each week
acc3 / used: none / 1x5 @7, 1x8 @7, 1x12 @8, 1x15 @8+ / 90s / warmup: none / progress: custom() { ...b1 }

// Use leg drive to move more than you could strict press.
Push Press, Barbell[9-12] / ...main3
Shoulder Press[9-12] / ...acc3
Lateral Raise[9-12] / ...acc3
Triceps Dip[9-12] / ...acc3
Skullcrusher[9-12] / ...acc3
Triceps Pushdown[9-12] / ...acc3

// ...Push Press, Barbell
Bench Press Wide Grip[9-12] / ...main3
Incline Bench Press, Dumbbell[9-12] / ...acc3
Chest Fly[9-12] / ...acc3
// Seated dip machine.
Triceps Dip, Leverage Machine[9-12] / ...acc3
// Two-hand overhead dumbbell extension.
Triceps Extension[9-12] / ...acc3

// Low bar, wide stance - built to move maximum weight.
lowbar: Squat[9-12] / ...main3
// Use the hack squat sled or smith machine.
Hack Squat, Smith Machine[9-12] / ...acc3
Step up[9-12] / ...acc3
// Dumbbell RDL.
Romanian Deadlift[9-12] / ...acc3
Back Extension[9-12] / ...acc3
